package com.gymmind.booking.api; import com.gymmind.booking.application.*; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/bookings") @SecurityRequirement(name="bearerAuth") public class BookingController{private final BookingService service;private final CurrentActorProvider actors;public BookingController(BookingService s,CurrentActorProvider a){service=s;actors=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ApiResponse<Void>book(@Valid@RequestBody BookRequest r){service.book(actors.requireCurrent(),new BookCourseCommand(null,r.memberId(),r.courseId()));return ApiResponse.success(null);}public record BookRequest(Long memberId,Long courseId){}}
